        ]);

        // =========================
        // DISPONIBILIDAD (lookup por código postal real)
        // =========================
        $cityIds = function (string $prefix, int $limit = 8): array {
            return DB::table('ubicaciones')
                ->where('codigo_postal', 'LIKE', $prefix . '%')
                ->orderBy('id_ubicacion')
                ->limit($limit)
                ->pluck('id_ubicacion')
                ->all();
        };

        $cobertura = [
            'nacional'   => array_merge($cityIds('28'), $cityIds('08'), $cityIds('46'), $cityIds('41'), $cityIds('50'), $cityIds('48'), $cityIds('29'), $cityIds('15'), $cityIds('33'), $cityIds('07')),
            'peninsula'  => array_merge($cityIds('28'), $cityIds('08'), $cityIds('46'), $cityIds('41'), $cityIds('50'), $cityIds('48'), $cityIds('29'), $cityIds('14'), $cityIds('30'), $cityIds('47')),
            'centro'     => array_merge($cityIds('28', 12), $cityIds('45'), $cityIds('19'), $cityIds('05'), $cityIds('40')),
            'cataluna'   => array_merge($cityIds('08', 12), $cityIds('17'), $cityIds('25'), $cityIds('43')),
            'andalucia'  => array_merge($cityIds('41'), $cityIds('29'), $cityIds('14'), $cityIds('18'), $cityIds('11'), $cityIds('21'), $cityIds('23'), $cityIds('04')),
            'norte'      => array_merge($cityIds('48'), $cityIds('20'), $cityIds('01'), $cityIds('39'), $cityIds('33'), $cityIds('15'), $cityIds('27'), $cityIds('32'), $cityIds('36')),
            'levante'    => array_merge($cityIds('46'), $cityIds('03'), $cityIds('12'), $cityIds('30')),
        ];

        // Mapeo de cobertura por tarifa (las grandes operan a nivel nacional;
        // independientes/cooperativas tienen cobertura más reducida)
        $tarifaCobertura = [
            // Luz
            1  => 'nacional',  2  => 'nacional',  3  => 'nacional',  4  => 'nacional',
            5  => 'nacional',  6  => 'peninsula', 7  => 'peninsula', 8  => 'peninsula',
            9  => 'peninsula', 10 => 'peninsula', 11 => 'peninsula', 12 => 'peninsula',
            13 => 'cataluna',  14 => 'levante',
            // Gas (gasoducto: peninsular)
            15 => 'peninsula', 16 => 'peninsula', 17 => 'peninsula', 18 => 'peninsula',
            19 => 'peninsula', 20 => 'peninsula',
            // Telefonía
            21 => 'nacional',  22 => 'nacional',  23 => 'nacional',  24 => 'nacional',
            25 => 'peninsula', 26 => 'peninsula', 27 => 'peninsula', 28 => 'peninsula',
            29 => 'peninsula', 30 => 'peninsula', 31 => 'peninsula', 32 => 'peninsula',
            33 => 'peninsula', 34 => 'peninsula', 35 => 'centro',    36 => 'centro',
            37 => 'nacional',  38 => 'nacional',
        ];

        $disponibilidadRows = [];
        foreach ($tarifaCobertura as $idTarifa => $zona) {
            foreach (array_unique($cobertura[$zona]) as $idUbicacion) {
                $disponibilidadRows[] = [
                    'id_tarifa'    => $idTarifa,
                    'id_ubicacion' => $idUbicacion,
                    'created_at'   => now(),
                    'updated_at'   => now(),
                ];
            }
        }

        foreach (array_chunk($disponibilidadRows, 500) as $chunk) {
            DB::table('disponibilidad')->insert($chunk);
        }
    }
